    """Shift each non-background cell down by one row, clipping at the bottom."""
    if not grid or not grid[0]:
        return [row[:] for row in grid]
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[background for _ in row] for row in grid]
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value != background and r + 1 < len(grid):
                out[r + 1][c] = value
